args.streamContent:
/**
 * Mock product photos of the Trail Runner 2, drawn as inline SVG so each
 * colorway (blue / black / grey) can reuse the same artwork.
 * `view` is one of: 'side' | 'angle' | 'sole'.
 */
export default function ShoeImage({ color, view, titleId }) {
  const { swatch, dark, light } = color

  return (
    <svg
      viewBox="0 0 600 400"
      role="img"
      aria-labelledby={titleId}
      className="shoe-svg"
      focusable="false"
    >
      <rect width="600" height="400" rx="12" fill="#f6f4ef" />
      {view === 'sole' ? (
        <g>
          {/* footprint outline */}
          <path
            d="M300 40 C360 40 385 90 388 140 C390 180 375 210 372 250 C369 300 380 340 360 362 C340 384 260 384 240 362 C220 340 231 300 228 250 C225 210 210 180 212 140 C215 90 240 40 300 40 Z"
            fill={dark}
            stroke={swatch}
            strokeWidth="6"
          />
          {/* lugs */}
          {Array.from({ length: 5 }).map((_, r) =>
            Array.from({ length: 3 }).map((_, c) => (
              <rect
                key={`${r}-${c}`}
                x={238 + c * 42}
                y={70 + r * 58}
                width="30"
                height="26"
                rx="7"
                fill={r === 2 ? '#e8590c' : light}
              />
            )),
          )}
          <text x="300" y="218" textAnchor="middle" fill="#ffffff" fontSize="18" fontWeight="700">
            TR2
          </text>
        </g>
      ) : (
        <g transform={view === 'angle' ? 'translate(600 0) scale(-1 1) rotate(-4 300 330)' : undefined}>
          {/* shadow */}
          <ellipse cx="300" cy="352" rx="230" ry="16" fill="#e3ded4" />
          {/* upper */}
          <path
            d="M62 300
               C56 258 72 234 102 224
               C132 214 156 204 176 180
               C196 156 210 120 236 105
               C258 92 288 95 308 112
               L362 152
               C402 182 432 212 472 230
               C512 247 550 256 564 268
               C576 278 576 292 568 300 Z"
            fill={swatch}
          />
          {/* heel counter */}
          <path
            d="M62 300 C56 258 72 234 102 224 C120 218 138 212 152 202 L168 300 Z"
            fill={dark}
          />
          {/* toe cap */}
          <path
            d="M472 230 C512 247 550 256 564 268 C576 278 576 292 568 300 L470 300 C452 272 452 250 472 230 Z"
            fill={dark}
          />
          {/* ankle collar */}
          <ellipse cx="252" cy="122" rx="46" ry="26" fill={dark} transform="rotate(-28 252 122)" />
          <ellipse cx="250" cy="124" rx="32" ry="16" fill="#f6f4ef" transform="rotate(-28 250 124)" />
          {/* laces */}
          {[0, 1, 2, 3, 4].map((i) => (
            <line
              key={i}
              x1={272 + i * 26}
              y1={142 + i * 18}
              x2={308 + i * 26}
              y2={126 + i * 18}
              stroke="#ffffff"
              strokeWidth="9"
              strokeLinecap="round"
            />
          ))}
          {/* swoosh-like accent stripe */}
          <path
            d="M150 236 C230 218 330 226 430 262"
            fill="none"
            stroke="#e8590c"
            strokeWidth="14"
            strokeLinecap="round"
          />
          {/* midsole */}
          <path
            d="M48 298 C200 312 420 312 570 298 C582 296 586 308 582 318 C578 328 562 332 542 332 L78 332 C58 332 46 324 44 312 C43 306 44 301 48 298 Z"
            fill="#ffffff"
            stroke="#d8d2c4"
            strokeWidth="2"
          />
          {/* orange midsole block */}
