args.streamContent:
import { useEffect, useState } from 'react'
import { PRODUCT } from '../data'
import ShoeImage from './ShoeImage'

/**
 * Photo carousel (APG carousel pattern): one photo at a time, previous/next
 * buttons wrap around, arrow keys also work when focus is inside the region.
 */
export default function Gallery({ color }) {
  const [index, setIndex] = useState(0)
  const views = PRODUCT.views

  // Reset to the first photo when the colorway changes.
  useEffect(() => {
    setIndex(0)
  }, [color.id])

  const go = (delta) => setIndex((i) => (i + delta + views.length) % views.length)

  const onKeyDown = (event) => {
    if (event.key === 'ArrowLeft') {
      event.preventDefault()
      go(-1)
    } else if (event.key === 'ArrowRight') {
      event.preventDefault()
      go(1)
    }
  }

  const current = views[index]
  const description = `${current.label} of the ${PRODUCT.name} in ${color.label.toLowerCase()}`

  return (
    <section
      className="gallery"
      role="group"
      aria-roledescription="carousel"
      aria-label="Product photos"
      onKeyDown={onKeyDown}
    >
      <div className="gallery-frame" aria-roledescription="slide" aria-label={`${index + 1} of ${views.length}`}>
        <ShoeImage color={color} view={current.id} titleId={`shoe-title-${current.id}-${color.id}`} />
        <span id={`shoe-title-${current.id}-${color.id}`} className="visually-hidden">
          {description}
        </span>
        <button
          type="button"
          className="gallery-btn prev"
          onClick={() => go(-1)}
          aria-label="Previous photo"
        >
          <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false">
            <path d="M15 5l-7 7 7 7" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </button>
        <button
          type="button"
          className="gallery-btn next"
          onClick={() => go(1)}
          aria-label="Next photo"
        >
          <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false">
            <path d="M9 5l7 7-7 7" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </button>
      </div>
      <p className="gallery-status" aria-live="polite">
        Photo {index + 1} of {views.length}: {description}
      </p>
    </section>
  )
}

