import { useEffect, useRef, useState } from 'react'
import { PRODUCT } from '../data'

/**
 * Price with an APG tooltip: the "i" trigger shows the tooltip on hover and
 * keyboard focus, Escape dismisses it, and aria-describedby links them.
 */
export default function PriceInfo() {
  const [open, setOpen] = useState(false)
  const wrapperRef = useRef(null)

  useEffect(() => {
    if (!open) return undefined
    const onKeyDown = (event) => {
      if (event.key === 'Escape') setOpen(false)
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [open])

  const price = new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: PRODUCT.currency,
  }).format(PRODUCT.price)

  return (
    <p className="price-row">
      <span className="price">{price}</span>
      <span
        ref={wrapperRef}
        className="tooltip-wrapper"
        onMouseEnter={() => setOpen(true)}
        onMouseLeave={() => setOpen(false)}
      >
        <button
          type="button"
          className="info-btn"
          aria-label="Price information"
          aria-describedby={open ? 'price-tooltip' : undefined}
          onFocus={() => setOpen(true)}
          onBlur={() => setOpen(false)}
          onClick={() => setOpen((o) => !o)}
        >
          i
        </button>
        {open && (
          <span role="tooltip" id="price-tooltip" className="tooltip">
            Price includes all applicable taxes.
          </span>
        )}
      </span>
    </p>
  )
}

