import { useRef } from 'react'
import { PRODUCT } from '../data'

/**
 * Color picker as an APG radio group: round swatches, roving tabindex,
 * arrow keys move and select, only the chosen color name is shown.
 */
export default function ColorSwatches({ color, onChange }) {
  const colors = PRODUCT.colors
  const refs = useRef([])

  const select = (id) => {
    const next = colors.findIndex((c) => c.id === id)
    onChange(colors[next])
    refs.current[next]?.focus()
  }

  const onKeyDown = (event, index) => {
    let next = null
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % colors.length
    if (event.key === 'ArrowLeft' || event.key === 'ArrowUp')
      next = (index - 1 + colors.length) % colors.length
    if (event.key === 'Home') next = 0
    if (event.key === 'End') next = colors.length - 1
    if (next !== null) {
      event.preventDefault()
      select(colors[next].id)
    }
  }

  return (
    <div className="color-picker">
      <p id="color-label" className="option-label">
        Color: <strong>{color.label}</strong>
      </p>
      <div role="radiogroup" aria-labelledby="color-label" className="swatches">
        {colors.map((c, i) => (
          <button
            key={c.id}
            ref={(el) => (refs.current[i] = el)}
            type="button"
            role="radio"
            aria-checked={c.id === color.id}
            tabIndex={c.id === color.id ? 0 : -1}
            aria-label={c.label}
            className={`swatch${c.id === color.id ? ' selected' : ''}`}
            style={{ backgroundColor: c.swatch }}
            onClick={() => select(c.id)}
            onKeyDown={(e) => onKeyDown(e, i)}
          />
        ))}
      </div>
    </div>
  )
}

