import { useEffect, useRef, useState } from 'react'
import { PRODUCT } from '../data'

/**
 * Size picker as an APG listbox: the list only opens on demand, only the
 * chosen size is shown when closed, and sold-out sizes are present but not
 * selectable (aria-disabled).
 */
export default function SizeSelector({ size, onChange, buttonRef }) {
  const sizes = PRODUCT.sizes
  const [open, setOpen] = useState(false)
  const [activeIndex, setActiveIndex] = useState(0)
  const listRef = useRef(null)
  const rootRef = useRef(null)

  const openList = (startIndex) => {
    const selectedIndex = sizes.findIndex((s) => size && s.us === size.us)
    setActiveIndex(startIndex ?? (selectedIndex >= 0 ? selectedIndex : 0))
    setOpen(true)
  }

  const closeList = ({ focusButton = true } = {}) => {
    setOpen(false)
    if (focusButton) buttonRef.current?.focus()
  }

  const choose = (option) => {
    if (!option.inStock) return
    onChange(option)
    closeList()
  }

  // Focus the active option whenever it changes while open.
  useEffect(() => {
    if (open) {
      listRef.current
        ?.querySelector(`#size-option-${sizes[activeIndex].us}`)
        ?.focus()
    }
  }, [open, activeIndex, sizes])

  // Close when clicking outside.
  useEffect(() => {
    if (!open) return undefined
    const onPointerDown = (event) => {
      if (!rootRef.current?.contains(event.target)) closeList({ focusButton: false })
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [open])

  const move = (next) => setActiveIndex(((next % sizes.length) + sizes.length) % sizes.length)

  const onButtonKeyDown = (event) => {
    if (event.key === 'ArrowDown' || event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      openList()
    } else if (event.key === 'ArrowUp') {
      event.preventDefault()
      openList(sizes.length - 1)
    }
  }

  const onListKeyDown = (event) => {
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault()
        move(activeIndex + 1)
        break
      case 'ArrowUp':
        event.preventDefault()
        move(activeIndex - 1)
        break
      case 'Home':
        event.preventDefault()
        move(0)
        break
      case 'End':
        event.preventDefault()
        move(sizes.length - 1)
        break
      case 'Enter':
      case ' ':
        event.preventDefault()
        choose(sizes[activeIndex])
        break
      case 'Escape':
        event.preventDefault()
        closeList()
        break
      case 'Tab':
        closeList({ focusButton: false })
        break
      default:
    }
  }

  return (
    <div className="size-picker" ref={rootRef}>
      <button
        type="button"
        ref={buttonRef}
        className="size-toggle"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label={size ? `Size, US ${size.us}, change size` : 'Select size'}
        onClick={() => (open ? closeList() : openList())}
        onKeyDown={onButtonKeyDown}
      >
        <span>{size ? `US ${size.us}` : 'Select size'}</span>
        <svg
          viewBox="0 0 24 24"
          width="18"
          height="18"
          aria-hidden="true"
          focusable="false"
          className={open ? 'chevron open' : 'chevron'}
        >
          <path d="M6 9l6 6 6-6" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </button>
      {open && (
        <ul
          role="listbox"
          aria-label="Size"
          className="size-list"
          ref={listRef}
          onKeyDown={onListKeyDown}
        >
          {sizes.map((option, i) => (
            <li
              key={option.us}
              id={`size-option-${option.us}`}
              role="option"
              aria-selected={size ? option.us === size.us : false}
              aria-disabled={!option.inStock}
              tabIndex={i === activeIndex ? 0 : -1}
              className={[
                'size-option',
                i === activeIndex ? 'active' : '',
                option.inStock ? '' : 'sold-out',
                size && option.us === size.us ? 'selected' : '',
              ]
                .filter(Boolean)
                .join(' ')}
              onClick={() => choose(option)}
              onMouseEnter={() => setActiveIndex(i)}
            >
              US {option.us}
              {!option.inStock && <span className="sold-out-note"> — sold out</span>}
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

