import { useEffect, useRef, useState } from 'react'
import { SIZE_CHART, sizeForFootLength } from '../data'

const FOCUSABLE =
  'button:not([disabled]), input:not([disabled]), [href], select, textarea, [tabindex]:not([tabindex="-1"])'

/**
 * Modal size guide (APG dialog pattern): opens over the page, traps focus,
 * closes with Escape or the close button, and returns focus to the trigger.
 * Enter a foot length to get a US or EU size recommendation.
 */
export default function SizeGuideDialog({ onClose, triggerRef }) {
  const [footLength, setFootLength] = useState('')
  const [unit, setUnit] = useState('us')
  const [result, setResult] = useState(null)
  const dialogRef = useRef(null)
  const inputRef = useRef(null)

  useEffect(() => {
    inputRef.current?.focus()
    const onKeyDown = (event) => {
      if (event.key === 'Escape') {
        event.preventDefault()
        onClose()
        return
      }
      if (event.key === 'Tab') {
        const focusables = dialogRef.current.querySelectorAll(FOCUSABLE)
        if (focusables.length === 0) return
        const first = focusables[0]
        const last = focusables[focusables.length - 1]
        if (event.shiftKey && document.activeElement === first) {
          event.preventDefault()
          last.focus()
        } else if (!event.shiftKey && document.activeElement === last) {
          event.preventDefault()
          first.focus()
        }
      }
    }
    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.removeEventListener('keydown', onKeyDown)
      triggerRef?.current?.focus()
    }
  }, [onClose, triggerRef])

  const findSize = (event) => {
    event.preventDefault()
    const match = sizeForFootLength(footLength)
    if (!match) {
      setResult('Enter your foot length in centimeters, for example 26.5.')
    } else {
      setResult(
        `For a foot length of ${footLength} cm we recommend size US ${match.us} (EU ${match.eu}).`,
      )
    }
  }

  return (
    <div className="dialog-overlay" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby="size-guide-title"
        className="dialog"
        ref={dialogRef}
      >
        <div className="dialog-header">
          <h2 id="size-guide-title">Size guide</h2>
          <button type="button" className="dialog-close" onClick={onClose} aria-label="Close size guide">
            <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" focusable="false">
              <path d="M6 6l12 12M18 6L6 18" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" />
            </svg>
          </button>
        </div>

        <form onSubmit={findSize} className="size-finder">
          <label htmlFor="foot-length">Foot length (cm)</label>
          <div className="size-finder-row">
            <input
              id="foot-length"
              ref={inputRef}
              type="text"
              inputMode="decimal"
              value={footLength}
              onChange={(e) => {
                setFootLength(e.target.value)
                setResult(null)
              }}
              placeholder="e.g. 26.5"
            />
            <fieldset className="unit-toggle">
              <legend className="visually-hidden">Size system</legend>
              <label>
                <input
                  type="radio"
                  name="unit"
                  value="us"
                  checked={unit === 'us'}
                  onChange={() => setUnit('us')}
                />
                US
              </label>
              <label>
                <input
                  type="radio"
                  name="unit"
                  value="eu"
                  checked={unit === 'eu'}
                  onChange={() => setUnit('eu')}
                />
                EU
              </label>
            </fieldset>
            <button type="submit" className="btn secondary">
              Find my size
            </button>
          </div>
          {result && (
            <p className="size-result" aria-live="polite">
              {result}
            </p>
          )}
        </form>

        <table className="size-chart">
          <caption>Foot length to size conversion</caption>
          <thead>
            <tr>
              <th scope="col">Foot length (cm)</th>
              <th scope="col">US</th>
              <th scope="col">EU</th>
            </tr>
          </thead>
          <tbody>
            {SIZE_CHART.map((row) => (
              <tr key={row.cm}>
                <td>{row.cm.toFixed(1)}</td>
                <td>{row.us}</td>
                <td>{row.eu}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

