import { PRODUCT } from '../data'

/**
 * Quantity stepper: type a number directly or change it one step at a time
 * with the minus/plus buttons. Values are clamped to 1..maxQuantity.
 */
export default function QuantityInput({ quantity, onChange }) {
  const max = PRODUCT.maxQuantity
  const clamp = (n) => Math.min(max, Math.max(1, n))

  return (
    <div className="quantity">
      <span id="quantity-label" className="option-label">
        Quantity
      </span>
      <div className="quantity-controls" role="group" aria-labelledby="quantity-label">
        <button
          type="button"
          aria-label="Decrease quantity"
          onClick={() => onChange(clamp(quantity - 1))}
          disabled={quantity <= 1}
        >
          −
        </button>
        <input
          type="text"
          inputMode="numeric"
          pattern="[0-9]*"
          aria-label="Quantity"
          value={quantity}
          onChange={(e) => {
            const digits = e.target.value.replace(/[^0-9]/g, '')
            if (digits === '') return
            onChange(clamp(Number(digits)))
          }}
          onBlur={(e) => {
            if (e.target.value === '') onChange(1)
          }}
        />
        <button
          type="button"
          aria-label="Increase quantity"
          onClick={() => onChange(clamp(quantity + 1))}
          disabled={quantity >= max}
        >
          +
        </button>
      </div>
    </div>
  )
}

