 * a time. Left/Right arrows move between tabs, Home/End jump to the ends.
 */
export default function InfoTabs() {
  const [selected, setSelected] = useState(0)
  const tabRefs = useRef([])

  const activate = (index) => {
    setSelected(index)
    tabRefs.current[index]?.focus()
  }

  const onKeyDown = (event, index) => {
    let next = null
    if (event.key === 'ArrowRight') next = (index + 1) % TABS.length
    if (event.key === 'ArrowLeft') next = (index - 1 + TABS.length) % TABS.length
    if (event.key === 'Home') next = 0
    if (event.key === 'End') next = TABS.length - 1
    if (next !== null) {
      event.preventDefault()
      activate(next)
    }
  }

  return (
    <section className="info-tabs" aria-label="More information">
      <h2>More information</h2>
      <div role="tablist" aria-label="Product information" className="tab-list">
        {TABS.map((tab, i) => (
          <button
            key={tab.id}
            ref={(el) => (tabRefs.current[i] = el)}
            type="button"
            role="tab"
            id={`tab-${tab.id}`}
            aria-selected={i === selected}
            aria-controls={`panel-${tab.id}`}
            tabIndex={i === selected ? 0 : -1}
            className={i === selected ? 'tab selected' : 'tab'}
            onClick={() => setSelected(i)}
            onKeyDown={(e) => onKeyDown(e, i)}
          >
            {tab.label}
          </button>
        ))}
      </div>
      {TABS.map((tab, i) => (
        <div
          key={tab.id}
          role="tabpanel"
          id={`panel-${tab.id}`}
          aria-labelledby={`tab-${tab.id}`}
          tabIndex={0}
          hidden={i !== selected}
          className="tab-panel"
        >
          <p>{tab.content.intro}</p>
          {tab.content.specs && (
            <ul>
              {tab.content.specs.map((spec) => (
                <li key={spec}>{spec}</li>
              ))}
            </ul>
          )}
          {tab.content.reviews && (
            <ul className="reviews">
              {tab.content.reviews.map((review) => (
                <li key={review.author}>
                  <span className="review-rating" aria-label={`Rated ${review.rating} out of 5`}>
                    {'★'.repeat(review.rating)}
                    <span aria-hidden="true" className="stars-off">
                      {'★'.repeat(5 - review.rating)}
                    </span>
                  </span>{' '}
                  <strong>{review.author}</strong>
                  <p>{review.text}</p>
                </li>
              ))}
            </ul>
          )}
        </div>
      ))}
    </section>
  )
}

