import { useRef, useState } from 'react'
import { PRODUCT } from './data'
import Header from './components/Header'
import Breadcrumbs from './components/Breadcrumbs'
import Gallery from './components/Gallery'
import PriceInfo from './components/PriceInfo'
import ColorSwatches from './components/ColorSwatches'
import SizeSelector from './components/SizeSelector'
import SizeGuideDialog from './components/SizeGuideDialog'
import QuantityInput from './components/QuantityInput'
import InfoTabs from './components/InfoTabs'
import FaqAccordion from './components/FaqAccordion'
import Footer from './components/Footer'

export default function App() {
  const [color, setColor] = useState(PRODUCT.colors[0])
  const [size, setSize] = useState(null)
  const [quantity, setQuantity] = useState(1)
  const [cartCount, setCartCount] = useState(0)
  const [saved, setSaved] = useState(false)
  const [sizeError, setSizeError] = useState(false)
  const [confirmation, setConfirmation] = useState('')
  const [guideOpen, setGuideOpen] = useState(false)

  const sizeButtonRef = useRef(null)
  const guideButtonRef = useRef(null)

  const addToCart = () => {
    if (!size) {
      setSizeError(true)
      setConfirmation('')
      sizeButtonRef.current?.focus()
      return
    }
    setSizeError(false)
    setCartCount((count) => count + quantity)
    setConfirmation(
      `Added to cart: ${quantity} × ${PRODUCT.name}, ${color.label.toLowerCase()}, size US ${size.us}.`,
    )
  }

  return (
    <>
      <Header cartCount={cartCount} />
      <main id="main" className="page">
        <Breadcrumbs />
        <div className="product-layout">
          <Gallery color={color} />
          <div className="product-info">
            <h1>{PRODUCT.name}</h1>
            <p className="tagline">Grip every trail, in any weather.</p>
            <PriceInfo />
            <ColorSwatches color={color} onChange={setColor} />

            <div className="size-row">
              <SizeSelector size={size} onChange={(s) => { setSize(s); setSizeError(false) }} buttonRef={sizeButtonRef} />
              <button
                type="button"
                className="link-btn"
                ref={guideButtonRef}
                onClick={() => setGuideOpen(true)}
              >
                Size guide
              </button>
            </div>
            {sizeError && (
              <p className="error" role="alert">
                Please pick a size before adding to cart.
              </p>
            )}

            <QuantityInput quantity={quantity} onChange={setQuantity} />

            <div className="actions">
              <button type="button" className="btn primary" onClick={addToCart}>
                Add to cart
              </button>
              <button
                type="button"
                className={`wishlist-btn${saved ? ' saved' : ''}`}
                aria-pressed={saved}
                aria-label={saved ? 'Remove from wishlist' : 'Save to wishlist'}
                onClick={() => setSaved((s) => !s)}
              >
                <svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" focusable="false">
                  <path
                    d="M12 21C7 16.5 3 13 3 8.8 3 6 5.2 4 7.8 4c1.7 0 3.2.9 4.2 2.3C13 4.9 14.5 4 16.2 4 18.8 4 21 6 21 8.8c0 4.2-4 7.7-9 12.2Z"
                    fill={saved ? 'currentColor' : 'none'}
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinejoin="round"
                  />
                </svg>
              </button>
            </div>
            <p className="confirmation" aria-live="polite">
              {confirmation}
            </p>
          </div>
        </div>

        <InfoTabs />
        <FaqAccordion />
      </main>
      <Footer />
      {guideOpen && (
        <SizeGuideDialog onClose={() => setGuideOpen(false)} triggerRef={guideButtonRef} />
      )}
    </>
  )
}

