  max-width: 44rem;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-item h3 {
  margin: 0;
}

.faq-item button {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  background: none;
  border: none;
  padding: 1rem 0.25rem;
  font-weight: 600;
  text-align: left;
}

.faq-panel p {
  margin: 0 0 1rem;
  padding: 0 0.25rem;
  color: var(--muted);
}

/* Dialog */
.dialog-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  display: grid;
  place-items: center;
  padding: 1rem;
  z-index: 50;
}

.dialog {
  background: var(--surface);
  border-radius: 12px;
  max-width: 32rem;
  width: 100%;
  max-height: 85vh;
  overflow: auto;
  padding: 1.5rem;
}

.dialog-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.dialog-header h2 {
  margin: 0;
}

.dialog-close {
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--surface);
  display: grid;
  place-items: center;
}

.size-finder label {
  font-weight: 600;
  display: block;
  margin: 1rem 0 0.35rem;
}

.size-finder-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
}

.size-finder-row input[type='text'] {
  width: 7rem;
  padding: 0.55rem 0.6rem;
  border: 1.5px solid var(--text);
  border-radius: 8px;
  font: inherit;
}

.unit-toggle {
  display: flex;
  gap: 0.75rem;
  border: none;
  margin: 0;
  padding: 0;
}

.unit-toggle label {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin: 0;
  font-weight: 500;
}

.size-result {
  font-weight: 700;
  color: #1d7a34;
}

.size-chart {
  width: 100%;
  border-collapse: collapse;
  margin-top: 1.25rem;
}

.size-chart caption {
  text-align: left;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.size-chart th,
.size-chart td {
  border: 1px solid var(--border);
  padding: 0.4rem 0.6rem;
  text-align: left;
}

.size-chart th {
  background: var(--surface-alt);
}

/* Footer */
.site-footer {
  background: var(--text);
  color: #f0ede6;
  margin-top: 3rem;
}

.footer-grid {
  max-width: 72rem;
  margin: 0 auto;
  padding: 2.5rem 1.5rem 1rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
  gap: 2rem;
}

.footer-section h2 {
  font-size: 1rem;
  margin: 0 0 0.75rem;
}

.footer-section ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}

.footer-section a {
  color: #f0ede6;
  text-decoration: none;
}

.footer-section a:hover {
  text-decoration: underline;
}

.footer-note {
  max-width: 72rem;
  margin: 0 auto;
  padding: 0 1.5rem 2rem;
  color: #b9b4a8;
  font-size: 0.85rem;
}

