  justify-content: space-between;
  gap: 1rem;
  min-width: 10rem;
  padding: 0.6rem 0.9rem;
  border: 1.5px solid var(--text);
  border-radius: 8px;
  background: var(--surface);
  font-weight: 600;
}

.chevron {
  transition: transform 0.15s ease;
}

.chevron.open {
  transform: rotate(180deg);
}

.size-list {
  position: absolute;
  z-index: 20;
  top: calc(100% + 0.35rem);
  left: 0;
  margin: 0;
  padding: 0.3rem;
  list-style: none;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.18);
  min-width: 12rem;
}

.size-option {
  padding: 0.5rem 0.75rem;
  border-radius: 6px;
  cursor: pointer;
}

.size-option.active {
  background: var(--surface-alt);
  outline: 2px solid var(--focus);
  outline-offset: -2px;
}

.size-option.selected {
  font-weight: 700;
}

.size-option.sold-out {
  color: var(--muted);
  cursor: not-allowed;
  text-decoration: line-through;
}

.sold-out-note {
  text-decoration: none;
  font-size: 0.85rem;
}

.link-btn {
  background: none;
  border: none;
  padding: 0.3rem 0;
  color: var(--link);
  text-decoration: underline;
  font-weight: 600;
}

.error {
  color: #b02a0a;
  font-weight: 600;
  margin: 0.25rem 0 0.75rem;
}

/* Quantity */
.quantity {
  margin: 1rem 0 1.25rem;
}

.quantity-controls {
  display: inline-flex;
  align-items: stretch;
  border: 1.5px solid var(--text);
  border-radius: 8px;
  overflow: hidden;
}

.quantity-controls button {
  width: 2.6rem;
  border: none;
  background: var(--surface);
  font-size: 1.25rem;
  font-weight: 700;
}

.quantity-controls button:disabled {
  color: var(--muted);
  cursor: not-allowed;
}

.quantity-controls input {
  width: 3.2rem;
  border: none;
  border-left: 1px solid var(--border);
  border-right: 1px solid var(--border);
  text-align: center;
  font: inherit;
  padding: 0.55rem 0;
}

/* Actions */
.actions {
  display: flex;
  gap: 0.75rem;
  align-items: center;
}

.btn {
  border-radius: 8px;
  padding: 0.8rem 1.6rem;
  font-weight: 700;
  border: 1.5px solid var(--text);
}

.btn.primary {
  background: var(--text);
  color: #fff;
  flex: 1;
}

.btn.secondary {
  background: var(--surface);
  color: var(--text);
}

.wishlist-btn {
  width: 3.1rem;
  height: 3.1rem;
  border-radius: 50%;
  border: 1.5px solid var(--text);
  background: var(--surface);
  display: grid;
  place-items: center;
  color: var(--text);
}

.wishlist-btn.saved {
  color: var(--accent);
  border-color: var(--accent);
}

.confirmation {
  min-height: 1.5rem;
  color: #1d7a34;
  font-weight: 600;
}

/* Tabs */
.info-tabs {
  margin-top: 3rem;
}

.tab-list {
  display: flex;
  gap: 0.25rem;
  border-bottom: 2px solid var(--border);
}

.tab {
  background: none;
  border: none;
  padding: 0.7rem 1.2rem;
  font-weight: 600;
  color: var(--muted);
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
}

.tab.selected {
  color: var(--text);
  border-bottom-color: var(--accent);
}

.tab-panel {
  padding: 1.25rem 0.25rem;
}

.reviews {
  list-style: none;
  padding: 0;
  display: grid;
  gap: 1rem;
}

.review-rating {
  color: var(--accent);
}

.stars-off {
  color: #c9c4b8;
}

/* FAQ */
.faq {
  margin-top: 2rem;
  max-width: 44rem;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-item h3 {
  margin: 0;
}

.faq-item button {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  background: none;
  border: none;
  padding: 1rem 0.25rem;
  font-weight: 600;
  text-align: left;
}

.faq-panel p {
  margin: 0 0 1rem;
  padding: 0 0.25rem;
  color: var(--muted);
}

/* Dialog */
.dialog-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  display: grid;
  place-items: center;
  padding: 1rem;
  z-index: 50;
}

.dialog {
  background: var(--surface);
  border-radius: 12px;
  max-width: 32rem;
  width: 100%;
  max-height: 85vh;
  overflow: auto;
  padding: 1.5rem;
}

.dialog-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.dialog-header h2 {
  margin: 0;
}

.dialog-close {
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--surface);
  display: grid;
  place-items: center;
}

.size-finder label {
  font-weight: 600;
  display: block;
  margin: 1rem 0 0.35rem;
}

.size-finder-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
}

.size-finder-row input[type='text'] {
  width: 7rem;
  padding: 0.55rem 0.6rem;
  border: 1.5px solid var(--text);
  border-radius: 8px;
  font: inherit;
}

.unit-toggle {
  display: flex;
  gap: 0.75rem;
  border: none;
  margin: 0;
  padding: 0;
}

.unit-toggle label {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin: 0;
  font-weight: 500;
}

.size-result {
  font-weight: 700;
  color: #1d7a34;
}

.size-chart {
  width: 100%;
  border-collapse: collapse;
  margin-top: 1.25rem;
}

.size-chart caption {
  text-align: left;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.size-chart th,
.size-chart td {
  border: 1px solid var(--border);
  padding: 0.4rem 0.6rem;
  text-align: left;
}

.size-chart th {
  background: var(--surface-alt);
}

/* Footer */
.site-footer {
  background: var(--text);
  color: #f0ede6;
  margin-top: 3rem;
}

.footer-grid {
  max-width: 72rem;
  margin: 0 auto;
  padding: 2.5rem 1.5rem 1rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
  gap: 2rem;
}

.footer-section h2 {
  font-size: 1rem;
  margin: 0 0 0.75rem;
}

.footer-section ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}

.footer-section a {
  color: #f0ede6;
  text-decoration: none;
}

.footer-section a:hover {
  text-decoration: underline;
}

.footer-note {
  max-width: 72rem;
  margin: 0 auto;
  padding: 0 1.5rem 2rem;
  color: #b9b4a8;
  font-size: 0.85rem;
}

