:root {
  --text: #1c1c1e;
  --muted: #4d4d52;
  --accent: #c2410c;
  --link: #0b5394;
  --border: #d8d2c4;
  --surface: #ffffff;
  --surface-alt: #f6f4ef;
  --focus: #0b5394;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: 'Helvetica Neue', Helvetica, Arial, system-ui, sans-serif;
  color: var(--text);
  background: var(--surface);
  line-height: 1.5;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 1rem;
  top: -4rem;
  z-index: 100;
  background: var(--text);
  color: #fff;
  padding: 0.6rem 1rem;
  border-radius: 6px;
  transition: top 0.15s ease;
}

.skip-link:focus-visible {
  top: 0.5rem;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

a {
  color: var(--link);
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}

/* Header */
.site-header {
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}

.header-bar {
  max-width: 72rem;
  margin: 0 auto;
  padding: 0.9rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 2rem;
}

.store-name {
  font-size: 1.6rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--text);
  text-decoration: none;
}

.nav-list {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-list a {
  color: var(--text);
  text-decoration: none;
  font-weight: 600;
}

.nav-list a:hover {
  text-decoration: underline;
}

.cart-link {
  margin-left: auto;
  position: relative;
  display: inline-flex;
  align-items: center;
  color: var(--text);
  padding: 0.35rem;
}

.cart-badge {
  position: absolute;
  top: -4px;
  right: -8px;
  min-width: 1.25rem;
  height: 1.25rem;
  padding: 0 0.25rem;
  border-radius: 999px;
  background: var(--accent);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 700;
  display: grid;
  place-items: center;
}

/* Layout */
.page {
  max-width: 72rem;
  margin: 0 auto;
  padding: 1rem 1.5rem 3rem;
}

.breadcrumbs ol {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  list-style: none;
  margin: 0.5rem 0 1.5rem;
  padding: 0;
  font-size: 0.95rem;
}

.breadcrumbs li:not(:last-child)::after {
  content: '/';
  margin-left: 0.4rem;
  color: var(--muted);
}

.breadcrumbs [aria-current='page'] {
  color: var(--muted);
}

.product-layout {
  display: grid;
  grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
  gap: 3rem;
}

@media (max-width: 56rem) {
  .product-layout {
    grid-template-columns: 1fr;
  }
}

/* Gallery */
.gallery-frame {
  position: relative;
}

.shoe-svg {
  display: block;
  width: 100%;
  height: auto;
  border: 1px solid var(--border);
  border-radius: 12px;
}

.gallery-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--surface);
  display: grid;
  place-items: center;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.15);
}

.gallery-btn.prev {
  left: 0.75rem;
}

.gallery-btn.next {
  right: 0.75rem;
}

.gallery-btn:hover {
  background: var(--surface-alt);
}

.gallery-status {
  text-align: center;
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0.6rem 0 0;
}

/* Product info */
.product-info h1 {
  margin: 0;
  font-size: 2rem;
}

.tagline {
  margin: 0.25rem 0 1rem;
  color: var(--muted);
}

.price-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0 0 1.25rem;
}

.price {
  font-size: 1.6rem;
  font-weight: 700;
}

.tooltip-wrapper {
  position: relative;
  display: inline-flex;
}

.info-btn {
  width: 1.4rem;
  height: 1.4rem;
  border-radius: 50%;
  border: 1.5px solid var(--muted);
  background: var(--surface);
  color: var(--muted);
  font-size: 0.85rem;
  font-weight: 700;
  line-height: 1;
  display: grid;
  place-items: center;
  padding: 0;
}

.tooltip {
  position: absolute;
  bottom: calc(100% + 0.5rem);
  left: 50%;
  transform: translateX(-50%);
  background: var(--text);
  color: #fff;
  padding: 0.45rem 0.7rem;
  border-radius: 6px;
  font-size: 0.85rem;
  white-space: nowrap;
  z-index: 10;
}

.option-label {
  font-weight: 600;
  margin: 0 0 0.5rem;
}

/* Color swatches */
.color-picker {
  margin-bottom: 1.25rem;
}

.swatches {
  display: flex;
  gap: 0.75rem;
}

.swatch {
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  border: 2px solid var(--border);
  padding: 0;
}

.swatch.selected {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

/* Size picker */
.size-row {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 0.5rem;
}

.size-picker {
  position: relative;
}

.size-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-width: 10rem;
  padding: 0.6rem 0.9rem;
  border: 1.5px solid var(--text);
  border-radius: 8px;
  background: var(--surface);
  font-weight: 600;
}

.chevron {
  transition: transform 0.15s ease;
}

.chevron.open {
  transform: rotate(180deg);
}

.size-list {
  position: absolute;
  z-index: 20;
  top: calc(100% + 0.35rem);
  left: 0;
  margin: 0;
  padding: 0.3rem;
  list-style: none;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.18);
  min-width: 12rem;
}

.size-option {
  padding: 0.5rem 0.75rem;
  border-radius: 6px;
  cursor: pointer;
}

.size-option.active {
  background: var(--surface-alt);
  outline: 2px solid var(--focus);
  outline-offset: -2px;
}

.size-option.selected {
  font-weight: 700;
}

.size-option.sold-out {
  color: var(--muted);
  cursor: not-allowed;
  text-decoration: line-through;
}

.sold-out-note {
  text-decoration: none;
  font-size: 0.85rem;
}

.link-btn {
  background: none;
  border: none;
  padding: 0.3rem 0;
  color: var(--link);
  text-decoration: underline;
  font-weight: 600;
}

.error {
  color: #b02a0a;
  font-weight: 600;
  margin: 0.25rem 0 0.75rem;
}

/* Quantity */
.quantity {
  margin: 1rem 0 1.25rem;
}

.quantity-controls {
  display: inline-flex;
  align-items: stretch;
  border: 1.5px solid var(--text);
  border-radius: 8px;
  overflow: hidden;
}

.quantity-controls button {
  width: 2.6rem;
  border: none;
  background: var(--surface);
  font-size: 1.25rem;
  font-weight: 700;
}

.quantity-controls button:disabled {
  color: var(--muted);
  cursor: not-allowed;
}

.quantity-controls input {
  width: 3.2rem;
  border: none;
  border-left: 1px solid var(--border);
  border-right: 1px solid var(--border);
  text-align: center;
  font: inherit;
  padding: 0.55rem 0;
}

/* Actions */
.actions {
  display: flex;
  gap: 0.75rem;
  align-items: center;
}

.btn {
  border-radius: 8px;
  padding: 0.8rem 1.6rem;
  font-weight: 700;
  border: 1.5px solid var(--text);
}

.btn.primary {
  background: var(--text);
  color: #fff;
  flex: 1;
}

.btn.secondary {
  background: var(--surface);
  color: var(--text);
}

.wishlist-btn {
  width: 3.1rem;
  height: 3.1rem;
  border-radius: 50%;
  border: 1.5px solid var(--text);
  background: var(--surface);
  display: grid;
  place-items: center;
  color: var(--text);
}

.wishlist-btn.saved {
  color: var(--accent);
  border-color: var(--accent);
}

.confirmation {
  min-height: 1.5rem;
  color: #1d7a34;
  font-weight: 600;
}

/* Tabs */
.info-tabs {
  margin-top: 3rem;
}

.tab-list {
  display: flex;
  gap: 0.25rem;
  border-bottom: 2px solid var(--border);
}

.tab {
  background: none;
  border: none;
  padding: 0.7rem 1.2rem;
  font-weight: 600;
  color: var(--muted);
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
}

.tab.selected {
  color: var(--text);
  border-bottom-color: var(--accent);
}

.tab-panel {
  padding: 1.25rem 0.25rem;
}

.reviews {
  list-style: none;
  padding: 0;
  display: grid;
  gap: 1rem;
}

.review-rating {
  color: var(--accent);
}

.stars-off {
  color: #c9c4b8;
}

/* FAQ */
.faq {
  margin-top: 2rem;
  max-width: 44rem;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-item h3 {
  margin: 0;
}

.faq-item button {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  background: none;
  border: none;
  padding: 1rem 0.25rem;
  font-weight: 600;
  text-align: left;
}

.faq-panel p {
  margin: 0 0 1rem;
  padding: 0 0.25rem;
  color: var(--muted);
}

/* Dialog */
.dialog-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  display: grid;
  place-items: center;
  padding: 1rem;
  z-index: 50;
}

.dialog {
  background: var(--surface);
  border-radius: 12px;
  max-width: 32rem;
  width: 100%;
  max-height: 85vh;
  overflow: auto;
  padding: 1.5rem;
}

.dialog-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.dialog-header h2 {
  margin: 0;
}

.dialog-close {
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--surface);
  display: grid;
  place-items: center;
}

.size-finder label {
  font-weight: 600;
  display: block;
  margin: 1rem 0 0.35rem;
}

.size-finder-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
}

.size-finder-row input[type='text'] {
  width: 7rem;
  padding: 0.55rem 0.6rem;
  border: 1.5px solid var(--text);
  border-radius: 8px;
  font: inherit;
}

.unit-toggle {
  display: flex;
  gap: 0.75rem;
  border: none;
  margin: 0;
  padding: 0;
}

.unit-toggle label {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin: 0;
  font-weight: 500;
}

.size-result {
  font-weight: 700;
  color: #1d7a34;
}

.size-chart {
  width: 100%;
  border-collapse: collapse;
  margin-top: 1.25rem;
}

.size-chart caption {
  text-align: left;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.size-chart th,
.size-chart td {
  border: 1px solid var(--border);
  padding: 0.4rem 0.6rem;
  text-align: left;
}

.size-chart th {
  background: var(--surface-alt);
}

/* Footer */
.site-footer {
  background: var(--text);
  color: #f0ede6;
  margin-top: 3rem;
}

.footer-grid {
  max-width: 72rem;
  margin: 0 auto;
  padding: 2.5rem 1.5rem 1rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
  gap: 2rem;
}

.footer-section h2 {
  font-size: 1rem;
  margin: 0 0 0.75rem;
}

.footer-section ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}

.footer-section a {
  color: #f0ede6;
  text-decoration: none;
}

.footer-section a:hover {
  text-decoration: underline;
}

.footer-note {
  max-width: 72rem;
  margin: 0 auto;
  padding: 0 1.5rem 2rem;
  color: #b9b4a8;
  font-size: 0.85rem;
}

